<?php
require 'init.php'; require_login(); require 'db.php';
if ($_SESSION['role'] !== 'employer') { header('Location: dashboard.php'); exit; }
$company=(int)$_SESSION['company_id']; $message='';
if(isset($_GET['resume'])) { $stmt=$pdo->prepare('SELECT resume_pdf FROM applications WHERE id=? AND company_id=?'); $stmt->execute([(int)$_GET['resume'],$company]); $pdf=$stmt->fetchColumn(); if(!$pdf){http_response_code(404); exit('Resume not found.');} header('Content-Type: application/pdf'); header('Content-Disposition: attachment; filename="resume.pdf"'); header('X-Content-Type-Options: nosniff'); header('Cache-Control: private, no-store'); echo $pdf; exit; }
if($_SERVER['REQUEST_METHOD']==='POST' && valid_token() && in_array($_POST['decision']??'',['Offered','Rejected'],true)){ $stmt=$pdo->prepare("UPDATE applications SET status=? WHERE id=? AND company_id=? AND status='Pending'"); $stmt->execute([$_POST['decision'],(int)($_POST['application_id']??0),$company]); $message=$stmt->rowCount()?'Decision saved.':'Application already reviewed or unavailable.'; }
$stmt=$pdo->prepare('SELECT company_name FROM companies WHERE id=?'); $stmt->execute([$company]); $name=$stmt->fetchColumn();
$stmt=$pdo->prepare('SELECT a.id,a.position,a.application_date,a.status,u.name,u.email FROM applications a JOIN users u ON a.user_id=u.id WHERE a.company_id=? ORDER BY a.id DESC'); $stmt->execute([$company]); $apps=$stmt->fetchAll(); $title='Employer Dashboard'; require 'header.php'; ?>
<p class="eyebrow">EMPLOYER PORTAL</p><h1><?= e($name) ?></h1><p class="muted">Review student applications and offer internship placements.</p><?php if($message): ?><p class="alert alert-info"><?= e($message) ?></p><?php endif; ?>
<section class="card panel"><h2>Applicants (<?= count($apps) ?>)</h2><div class="table-responsive"><table class="table table-dark align-middle"><thead><tr><th>Student</th><th>Position</th><th>Date</th><th>Resume</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$apps): ?><tr><td colspan="6">No applications received yet.</td></tr><?php endif; ?><?php foreach($apps as $a): ?><tr><td><?= e($a['name']) ?><br><small><?= e($a['email']) ?></small></td><td><?= e($a['position']) ?></td><td><?= e($a['application_date']) ?></td><td><a href="employer.php?resume=<?= $a['id'] ?>">Download PDF</a></td><td><?= e($a['status']) ?></td><td><?php if($a['status']==='Pending'): ?><form method="post"><input type="hidden" name="csrf" value="<?= e(token()) ?>"><input type="hidden" name="application_id" value="<?= $a['id'] ?>"><button class="btn btn-success btn-sm" name="decision" value="Offered">Offer Internship</button> <button class="btn btn-outline-danger btn-sm" name="decision" value="Rejected">Reject</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php require 'footer.php'; ?>
